-- Entrepreneurship final module. Run seed_ent_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'entrepreneurship';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: My Business Plan and Stewardship Reflection$j$, $j${"prompt": "Create a business plan and reflection of at least 800 words in total. Use a sample or practice business only. Do not include real bank account numbers, Social Security numbers, passwords, home addresses, phone numbers or any private details about yourself, your family or other people. Share your plan with a parent, guardian or teacher for review before you present it to anyone. This plan is practice and general education, not legal, tax or financial advice, and you must not start a real business, sign a contract, borrow money or accept money without an adult.\n\nPart 1: Executive Summary and Company Description. Name your business, state the idea, the mission and three values, and choose a legal structure with a reason. Note that real legal choices require professional advice.\nPart 2: Market Analysis. Describe your target customer, five findings from research or interviews with at least ten possible customers, two direct and two indirect competitors, your value proposition and a four box SWOT.\nPart 3: Marketing and Sales Plan. Describe the four Ps, your brand, an honest advertisement, a sales pitch and your customer service and refund policy.\nPart 4: Operations and People Plan. Describe suppliers, inventory, quality and safety rules, a weekly checklist, online safety rules and the people you would need, including fair pay and child labor limits.\nPart 5: Financial Plan. Using sample figures only, list startup costs, price your product with a markup, compute the break even point, forecast six months of revenue and profit, describe your cash flow, taxes you would set aside and a sensitivity check. Show your work.\nPart 6: Risk, Giving and Growth. Name three risks with a response for each, describe a giving plan and explain one growth step you would take only after a successful pilot.\nPart 7: Pitch. Write a two minute pitch that answers the six pitch questions.\nPart 8: Faith and Reflection. Apply at least three Scripture passages from the King James Version, such as Proverbs 22:29, Luke 14:28, Colossians 3:23, Proverbs 3:9 or Matthew 25:14 to 30, to your plan, and explain what faithful stewardship means to you.", "rubric": "100 points. Part 1, summary and description: 10 points. Part 2, market analysis: 15 points. Part 3, marketing and sales: 15 points. Part 4, operations and people: 10 points. Part 5, financial plan: 20 points. Part 6, risk, giving and growth: 10 points. Part 7, pitch: 10 points. Part 8, faith and reflection: 5 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing. Deduct points if private information or real account numbers appear in the submission."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: My Business Plan and Stewardship Reflection$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Entrepreneurship$j$, $j${"questions": [{"q": "An entrepreneur is a person who:", "options": ["Never serves customers", "Sees a need and organizes resources to meet it", "Only works for others", "Avoids all risk"]}, {"q": "Proverbs 11:1 says a false balance is:", "options": ["A profit", "An abomination to the LORD", "A good name", "A smart tool"]}, {"q": "A business structure that can protect an owner's personal property from many business debts is the:", "options": ["Gift", "Hobby", "LLC", "Sole proprietorship"]}, {"q": "A target market is:", "options": ["A tax", "The specific group you serve best", "Only family", "Everyone in the world"]}, {"q": "A value proposition explains:", "options": ["Your home address", "Your tax bracket", "Why a customer should choose you", "Your age"]}, {"q": "An item costs 20 dollars and you add a 50 percent markup. The price is:", "options": ["30 dollars", "25 dollars", "10 dollars", "40 dollars"]}, {"q": "Revenue of 900 dollars and expenses of 650 dollars give a profit of:", "options": ["650 dollars", "250 dollars", "1550 dollars", "900 dollars"]}, {"q": "Fixed costs 400 dollars, price 9 dollars and variable cost 4 dollars. Break even units are:", "options": ["80", "100", "400", "44"]}, {"q": "Romans 13:7 teaches us to:", "options": ["Hide income", "Render to all their dues", "Ignore the law", "Avoid records"]}, {"q": "The first step in handling a complaint is to:", "options": ["Blame the customer", "Listen without interrupting", "Hang up", "Argue"]}, {"q": "A student starting a real business should:", "options": ["Meet strangers alone", "Involve a parent or guardian", "Post a home address online", "Hide it from adults"]}, {"q": "Mark 10:43 and 44 teaches that the greatest leader is a:", "options": ["Critic", "Servant", "Competitor", "Boss only"]}, {"q": "Insurance transfers part of a risk to an insurer in exchange for a:", "options": ["Grant", "Premium", "Tithe", "Dividend"]}, {"q": "A sensitivity check in a financial plan asks:", "options": ["What your name is", "What happens if sales or costs change", "Who your friends are", "What color your logo is"]}, {"q": "In the parable of the talents in Matthew 25, the master praised servants who were:", "options": ["Faithful with what they had", "Careless", "Proud", "Fearful and hidden"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Entrepreneurship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,2,1,2,0,1,0,1,1,1,1,1,1,0}'::int[], array[$j$Entrepreneurs meet needs through business.$j$,$j$Honest weights please God.$j$,$j$LLC stands for limited liability company.$j$,$j$Targeting helps you serve well.$j$,$j$It states the benefit you provide.$j$,$j$50 percent of 20 is 10, so the price is 30.$j$,$j$900 minus 650 is 250.$j$,$j$Margin is 5 and 400 divided by 5 is 80.$j$,$j$Honest taxes are part of citizenship.$j$,$j$Listening shows respect.$j$,$j$Adult involvement protects young people.$j$,$j$Christian leadership is service.$j$,$j$Premiums buy coverage.$j$,$j$It tests assumptions.$j$,$j$Faithful stewardship is rewarded.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Entrepreneurship$j$ on conflict (item_id) do nothing;
end
$seed$;
